func insert(_ intervals: [[Int]], _ newInterval: [Int]) -> [[Int]] {
    var result: [[Int]] = [], i = 0, cur = newInterval
    while i < intervals.count && intervals[i][1] < cur[0] { result.append(intervals[i]); i += 1 }
    while i < intervals.count && intervals[i][0] <= cur[1] {
        cur = [min(cur[0], intervals[i][0]), max(cur[1], intervals[i][1])]; i += 1
    }
    result.append(cur)
    return result + intervals[i...]
}
